input.new_string:
  : > "$ARCHIVE.tmp"
  n=$(awk -F'\t' -v c="$2" -v t="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print > t; next } { d++ } END { print d+0 }' "$ARCHIVE")
  mv "$ARCHIVE.tmp" "$ARCHIVE"
  echo "purged $n row(s) before $2 from $ARCHIVE" ;;
*) echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2 ;;

